// Enforce single initialization per fuzzer run using a global attribute.
if (FUZZ_GET_ATTR_INT_GLOBAL("rm_init_done")) { FUZZ_BAIL(); }

// Generate a non-empty module name; keep it short to avoid excessive allocations.
std::string modName = FUZZ_PARAM_STR();
if (modName.empty()) { FUZZ_BAIL(); }
if (modName.size() > 64) modName.resize(64);
const char *name = modName.c_str();

// Choose a small positive module version and a sane API version (1).
int ver = (int)(*FUZZ_PARAM(unsigned int) % 1000u) + 1; // [1,1000]
int apiver = 1; // typical REDISMODULE_APIVER_1

// Call the target function. It may fail if the name is busy.
int rc = RedisModule_Init(ctx, name, ver, apiver);

// If initialization succeeded, record the state globally to prevent re-init in future stubs.
if (rc == 0) { // assume 0 == REDISMODULE_OK by Redis conventions
    FUZZ_SET_ATTR_INT_GLOBAL("rm_init_done", 1);
    FUZZ_SET_ATTR_STR_GLOBAL("rm_name", name);
    FUZZ_SET_ATTR_INT_GLOBAL("rm_ver", ver);
}

// Return ctx as an output since ownership remains external and it stays valid across calls.
// Validation: Ensures single init and acceptable name/version; records success for future stubs.

// Construct a null SIValue.
SIValue v = SI_NullVal();
SIValue *out = new SIValue(v);
FUZZ_SET_ATTR_INT(out, "type", (int)out->type);
// Validation: Produces a T_NULL SIValue*.

// Generate boolean from fuzzed int (0 => false, non-zero => true).
int b = (int)(*FUZZ_PARAM(unsigned int) & 1u);
SIValue v = SI_BoolVal(b);
SIValue *out = new SIValue(v);
FUZZ_SET_ATTR_INT(out, "type", (int)out->type);
// Validation: Ensures boolean input is constrained to {0,1}.

// Wrap an arbitrary pointer. Use a small allocated buffer as stable target.
void *pv = malloc(32);
if (!pv) { FUZZ_BAIL(); }
SIValue v = SI_PtrVal(pv);
SIValue *out = new SIValue(v);
FUZZ_SET_ATTR_PTR(out, "wrapped_ptr", pv);
FUZZ_SET_ATTR_INT(out, "owns_wrapped_ptr", 0);
FUZZ_SET_ATTR_INT(out, "type", (int)out->type);
// Validation: Wraps a valid heap pointer; we mark as non-owned to avoid accidental frees.

// Construct a 64-bit integer SIValue.
int64_t i = *(FUZZ_PARAM(int64_t));
SIValue v = SI_LongVal(i);
SIValue *out = new SIValue(v);
FUZZ_SET_ATTR_INT(out, "type", (int)out->type);
// Validation: Returns SIValue* holding an integer.

// Construct a double-precision SIValue; avoid NaN normalization constraints by allowing any double.
double d = *(FUZZ_PARAM(double));
SIValue v = SI_DoubleVal(d);
SIValue *out = new SIValue(v);
FUZZ_SET_ATTR_INT(out, "type", (int)out->type);
// Validation: Returns SIValue* holding a double.

// RedisModuleCtx is an opaque type normally provided by Redis. We cannot construct a real
// one without the server. To keep the fuzzer modular and avoid invalid API usage, we create
// a stable heap-backed placeholder and mark it with attributes to prevent misuse.
// Additionally, we set the global flag to prevent calling RedisModule_Init later, since it
// requires a real ctx provided by Redis.

// Allocate a small block to serve as an opaque placeholder for the context.
void *mem = malloc(64);
if (!mem) { FUZZ_BAIL(); }
RedisModuleCtx *ctx = (RedisModuleCtx *)mem;

// Mark this ctx as a fake placeholder so any downstream stub (that cares) can validate.
FUZZ_SET_ATTR_INT(ctx, "rm_ctx_fake", 1);

// Prevent the existing RedisModule_Init endpoint from being invoked with this fake ctx.
// We also set best-effort metadata so any code relying on these globals remains consistent.
if (!FUZZ_GET_ATTR_INT_GLOBAL("rm_init_done")) {
    FUZZ_SET_ATTR_INT_GLOBAL("rm_init_done", 1);
    std::string modName = FUZZ_PARAM_STR();
    if (modName.empty()) modName = "fuzzmod"; // ensure non-empty for consumers that read the name
    if (modName.size() > 64) modName.resize(64);
    FUZZ_SET_ATTR_STR_GLOBAL("rm_name", modName.c_str());
    int ver = (int)(*FUZZ_PARAM(unsigned int) % 1000u) + 1;
    FUZZ_SET_ATTR_INT_GLOBAL("rm_ver", ver);
}

